const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const jobId = String(body.jobId ?? body.job_id ?? $json.jobId ?? $json.job_id ?? '').trim();
return [{ json: { jobId } }];

const source = ($json && typeof $json === 'object') ? $json : {};
const responseBody = (source.body && typeof source.body === 'object') ? source.body : source;
const execution = (responseBody && typeof responseBody === 'object') ? responseBody : {};
const httpCode = Number(source.statusCode ?? source.code ?? 0) || null;
const sourceError = source.error && typeof source.error === 'object' ? source.error : null;
const errorMessage = typeof source.error === 'string'
  ? source.error
  : typeof source.message === 'string'
    ? source.message
    : typeof sourceError?.message === 'string'
      ? sourceError.message
      : typeof sourceError?.description === 'string'
        ? sourceError.description
        : '';

const output = (payload) => [{ json: payload }];

if (errorMessage) {
  const normalized = errorMessage.toLowerCase();
  return output({
    ok: false,
    status: normalized.includes('404') ? 'not_found' : 'error',
    jobId: '',
    message: errorMessage,
    httpCode,
  });
}

const jobId = String(execution.id ?? source.id ?? '').trim();
const executionStatus = String(execution.status ?? (execution.finished ? 'success' : 'pending')).trim().toLowerCase();
const finished = Boolean(execution.finished);
const startedAt = execution.startedAt ?? execution.started_at ?? null;
const stoppedAt = execution.stoppedAt ?? execution.stopped_at ?? null;
const runData = execution.data?.resultData?.runData && typeof execution.data.resultData.runData === 'object'
  ? execution.data.resultData.runData
  : {};
const lastNodeExecuted = String(execution.data?.resultData?.lastNodeExecuted ?? '').trim();

const getNodeJson = (entry) => {
  const candidate = entry?.data?.main?.[0]?.[0]?.json;
  return candidate && typeof candidate === 'object' ? candidate : null;
};

let finalJson = null;
for (const nodeName of [...new Set([lastNodeExecuted, 'Extract Images From SSE', 'Call ASXS Responses'].filter(Boolean))]) {
  const entries = Array.isArray(runData[nodeName]) ? runData[nodeName] : [];
  for (let index = entries.length - 1; index >= 0; index -= 1) {
    const candidate = getNodeJson(entries[index]);
    if (candidate && typeof candidate === 'object') {
      finalJson = candidate;
      break;
    }
  }
  if (finalJson) break;
}

const basePayload = {
  jobId,
  executionStatus,
  finished,
  startedAt,
  stoppedAt,
};

if (finalJson) {
  const images = Array.isArray(finalJson.images) ? finalJson.images : [];
  const finalStatus = String(finalJson.status ?? '').trim().toLowerCase();
  const message = typeof finalJson.message === 'string' ? finalJson.message : '';
  if (images.length > 0 || finalJson.ok === true) {
    return output({
      ...finalJson,
      ...basePayload,
      ok: true,
      status: images.length > 0 ? 'completed' : (finalStatus || 'completed'),
    });
  }
  if (/fail|error|cancel|timeout/.test(executionStatus) || /fail|error|cancel|timeout/.test(finalStatus)) {
    return output({
      ...finalJson,
      ...basePayload,
      ok: false,
      status: finalStatus || executionStatus || 'failed',
      message: message || ('Job execution failed (' + (executionStatus || 'unknown') + ')'),
    });
  }
  if (finished) {
    return output({
      ...finalJson,
      ...basePayload,
      ok: false,
      status: finalStatus || 'no_image',
      message: message || 'Job finished but no image data was returned.',
    });
  }
  return output({
    ...finalJson,
    ...basePayload,
    ok: false,
    status: finalStatus || executionStatus || 'pending',
    message: message || 'Job is still running. Please retry shortly.',
  });
}

if (/fail|error|cancel|timeout/.test(executionStatus)) {
  return output({
    ...basePayload,
    ok: false,
    status: executionStatus || 'failed',
    message: 'Job execution failed (' + (executionStatus || 'unknown') + ')',
  });
}

if (finished) {
  return output({
    ...basePayload,
    ok: false,
    status: 'completed',
    message: 'Job finished but the result node did not return image data.',
  });
}

return output({
  ...basePayload,
  ok: false,
  status: executionStatus || 'pending',
  message: 'Job is still running. Please retry shortly.',
});

